set -e
git fetch {upstream_remote}
base=$(git merge-base HEAD {upstream_remote}/{upstream_branch})
git merge --no-commit --no-ff {upstream_remote}/{upstream_branch} || true
while IFS= read -r f; do
  case "$f" in
    *[Ll][Oo][Cc][Kk]*) ;;
    *) continue ;;
  esac
  git show HEAD:"$f" > "$f"
  python3 - "$f" "$base" "{upstream_remote}/{upstream_branch}" <<'PY'
import re
import subprocess
import sys

path, base, theirs = sys.argv[1], sys.argv[2], sys.argv[3]

def show(ref):
    p = subprocess.run(['git', 'show', ref + ':' + path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if p.returncode != 0:
        return []
    return p.stdout.decode('utf-8', 'surrogateescape').splitlines()

ours = show('HEAD')
theirs_lines = show(theirs)
p = subprocess.run(['git', 'diff', '--unified=0', '--no-color', base, theirs, '--', path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
if p.returncode == 0:
    diff = p.stdout.decode('utf-8', 'surrogateescape')
else:
    diff = ''
hunks = []
cur = None
for line in diff.splitlines():
    if line.startswith('@@'):
        m = re.match(r'@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@', line)
        if not m:
            continue
        cur = dict(start=int(m.group(1)), added=[], removed=False)
        hunks.append(cur)
    elif cur is not None:
        if line.startswith('+'):
            cur['added'].append(line[1:])
        elif line.startswith('-'):
            cur['removed'] = True
cursor = 0
for h in hunks:
    if h['removed'] or not h['added']:
        continue
    to_add = [l for l in h['added'] if l not in ours]
    if not to_add:
        continue
    next_idx = h['start'] - 1 + len(h['added'])
    next_anchor = theirs_lines[next_idx] if next_idx < len(theirs_lines) else None
    prev_anchor = theirs_lines[h['start'] - 2] if h['start'] >= 2 else None
    idx = None
    if next_anchor is not None:
        try:
            idx = ours.index(next_anchor, cursor)
        except ValueError:
            pass
    if idx is None and prev_anchor is not None:
        try:
            j = ours.index(prev_anchor, cursor)
            idx = j + 1
        except ValueError:
            pass
    if idx is None:
        idx = len(ours)
    ours[idx:idx] = to_add
    cursor = idx + len(to_add)
with open(path, 'w', encoding='utf-8', errors='surrogateescape') as fh:
    fh.write('\n'.join(ours))
    if ours:
        fh.write('\n')
PY
  git add "$f"
done < <(
  comm -12 \
    <(git diff --name-only -z "$base" HEAD | tr '\0' '\n' | sort -u) \
    <(git diff --name-only -z "$base" {upstream_remote}/{upstream_branch} | tr '\0' '\n' | sort -u)
)
git commit --no-edit
